sys_ui_action.script:
// Client-side script
function requestHRDocument() {
    // 1. Client-side validation: Ensure Document Type is selected
    var docType = g_form.getValue('u_document_type');
    if (!docType || docType === '') {
        g_form.hideFieldMsg('u_document_type');
        g_form.showFieldMsg('u_document_type', 'Please select a Document Type before requesting.', 'error');
        return false;
    }

    // 2. Trigger server execution
    gsftSubmit(null, g_form.getFormElement(), 'request_hr_document');
}

// Server-side script execution
if (typeof window == 'undefined') {
    createRecordAndRedirect();
}

function createRecordAndRedirect() {
    var targetEmployee = current.getValue('u_employee'); 
    var docType = current.getValue('u_document_type');

    // Create new record in Employee Document table (x_2182380_pwcnow_employee_document)
    var grDoc = new GlideRecord('x_2182380_pwcnow_employee_document');
    grDoc.initialize();
    grDoc.setValue('u_employee', targetEmployee); 
    grDoc.setValue('u_document_type', docType);
    grDoc.setValue('u_status', 'requested');

    var newSysId = grDoc.insert();

    if (newSysId) {
        // Explicitly fire event for "Document Required Alert"
        gs.eventQueue(
            'x_2182380_pwcnow.document_required_alert', 
            grDoc, 
            targetEmployee, 
            docType
        );

        gs.addInfoMessage('Document request created successfully for the employee.');

        // Redirect to Employee Document list filtered by employee
        action.setRedirectURL('x_2182380_pwcnow_employee_document_list.do?sysparm_query=u_employee=' + targetEmployee);
    }
}
